<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\Api\{AuthController,BookingController,DashboardController,ExpensePaymentController,ResourceController};
Route::post('/login',[AuthController::class,'login']);
Route::middleware('auth:sanctum')->group(function(){Route::get('/reports/cash-flow',\App\Http\Controllers\Api\PaymentHistoryController::class)->name('reports.cash-flow');Route::get('/payment-history',\App\Http\Controllers\Api\PaymentHistoryController::class);Route::get('/expenses/payees',[ResourceController::class,'payees']);Route::post('/purchases',[ResourceController::class,'storePurchase'])->name('purchases.store');Route::put('/purchases/{id}',[ResourceController::class,'updatePurchase'])->name('purchases.update');Route::post('/logout',[AuthController::class,'logout']);Route::get('/user',fn(\Illuminate\Http\Request $r)=>$r->user());Route::get('/dashboard',DashboardController::class);Route::apiResource('bookings',BookingController::class);Route::post('/expenses/{expense}/payments',[ExpensePaymentController::class,'store']);Route::delete('/expenses/{expense}/payments/{payment}',[ExpensePaymentController::class,'destroy']);foreach(['customers','menu-items','packages','expenses','payments','suppliers','purchase-types'] as $resource){Route::get($resource,[ResourceController::class,'index'])->defaults('resource',$resource);Route::post($resource,[ResourceController::class,'store'])->defaults('resource',$resource);Route::get("$resource/{id}",[ResourceController::class,'show'])->defaults('resource',$resource);Route::put("$resource/{id}",[ResourceController::class,'update'])->defaults('resource',$resource);Route::delete("$resource/{id}",[ResourceController::class,'destroy'])->defaults('resource',$resource);}});
